#!/usr/bin/env node
/**
 * Mirror the CANONICAL web-app supplement catalog into the landing site.
 *
 * WHY THIS EXISTS
 * ---------------
 * The landing site and the web app each ship a static `catalog.json`. They
 * MUST show the same supplement catalog (the landing is the indexed SEO
 * surface; the web app's catalog pages are noindex and defer to it). But they
 * used to be generated by two different exporters that silently drifted:
 *   - formulate-web/scripts/export-catalog.py  (canonical, maintained — reads
 *     the desktop DB *and* merges items.ndjson; ~266 products / 248 scored)
 *   - formulate-landing/scripts/export-catalog.py  (older fork — DB-published
 *     families only, no NDJSON merge; ~217 — and at one point it couldn't even
 *     read the now-encrypted DB and froze at 1 scored product)
 *
 * The fix is to stop re-deriving the landing catalog and instead MIRROR the
 * web app's catalog, which is the single source of truth. This script:
 *   1. copies formulate-web/src/data/catalog.json  -> landing src/data/catalog.json
 *   2. copies every product image the catalog references from the web app's
 *      public/ into the landing's public/ (so the /images/products/... URLs +
 *      their ?v= cache-buster tokens resolve identically on both sites)
 *
 * It is the landing's catalog step (see sync-catalog.sh). The desktop publish
 * pipeline keeps the WEB catalog fresh; running this mirrors that into the
 * landing. After running, commit catalog.json + the new public/images dirs
 * together and push (Vercel auto-deploys main).
 *
 * NOTE: the web app's live `/catalog` may show MORE than this static set
 * because it overlays API-"promoted" (webapp-published) supplements at runtime
 * via /api/v1/catalog/promoted. Those aren't in either static catalog.json;
 * draining them via a desktop publish folds them into the web catalog, which
 * the next run of this script then mirrors.
 *
 * Usage:  node scripts/sync-from-web.mjs    (or: npm run sync)
 * Env:    FORMULATE_WEB_DIR overrides the web-app repo location.
 */

import { existsSync, readFileSync, writeFileSync, cpSync, copyFileSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { makeThumbs } from "./make-thumbs.mjs";

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const LANDING_ROOT = resolve(SCRIPT_DIR, "..");
const WEB_ROOT =
  process.env.FORMULATE_WEB_DIR ||
  resolve(LANDING_ROOT, "..", "formulate-web");

const WEB_CATALOG = join(WEB_ROOT, "src", "data", "catalog.json");
const WEB_IMAGES = join(WEB_ROOT, "public", "images", "products");
const LANDING_CATALOG = join(LANDING_ROOT, "src", "data", "catalog.json");
const LANDING_IMAGES = join(LANDING_ROOT, "public", "images", "products");

function die(msg) {
  console.error(`ERROR: ${msg}`);
  process.exit(1);
}

if (!existsSync(WEB_CATALOG)) {
  die(
    `web catalog not found at ${WEB_CATALOG}\n` +
      `Set FORMULATE_WEB_DIR to the formulate-web repo, and make sure its ` +
      `catalog.json is up to date (run the web export / desktop publish first).`,
  );
}

const raw = readFileSync(WEB_CATALOG, "utf8");
let catalog;
try {
  catalog = JSON.parse(raw);
} catch (e) {
  die(`web catalog.json is not valid JSON: ${e.message}`);
}

const products = Array.isArray(catalog.products) ? catalog.products : [];
const brands = Array.isArray(catalog.brands) ? catalog.brands : [];
// Safety: never overwrite a populated landing catalog with an empty/broken one.
const scored = products.filter((p) => !p.is_draft && p.score != null).length;
if (scored < 1) {
  die(
    `web catalog has ${scored} scored products — refusing to mirror a broken ` +
      `catalog over the landing. Regenerate the web catalog first.`,
  );
}

// 1) Mirror the catalog JSON (2-space pretty + trailing newline = prior format).
writeFileSync(LANDING_CATALOG, JSON.stringify(catalog, null, 2) + "\n");

// 2) Copy every referenced product image dir from the web app's public/.
const dirs = new Set();
for (const p of products) {
  for (const u of [p.image_url, ...(p.gallery_images || [])]) {
    if (!u) continue;
    const m = /^\/images\/products\/([^?]+)\//.exec(u);
    if (m) dirs.add(m[1]); // "<brand>/<family>"
  }
}

mkdirSync(LANDING_IMAGES, { recursive: true });
let copied = 0;
let missing = 0;
for (const d of dirs) {
  const src = join(WEB_IMAGES, d);
  const dest = join(LANDING_IMAGES, d);
  if (existsSync(src)) {
    // Recursive copy; overwrites so updated images + ?v= tokens stay in sync.
    cpSync(src, dest, { recursive: true });
    copied++;
  } else if (!existsSync(dest)) {
    missing++;
  }
}

// 3) Mirror the WHOLE-FOODS catalog too.
//
// This step did not exist, and nothing else mirrored it either — so while the
// supplement catalog was kept in step by this script, whole foods drifted
// silently. Landing froze at the 2026-08-22 export while web moved to 08-26
// (the bioactive pillar switched to measured flavonoid content), and the live
// site scored Almonds 89/A for four days while the current engine said 97/A+.
// Whole-food scores drive /foods, /foods/best/* and every video built from the
// catalog, so a silent 8-point drift is not cosmetic.
const WEB_FOODS = join(WEB_ROOT, "src", "data", "whole-foods-catalog.json");
const LANDING_FOODS = join(LANDING_ROOT, "src", "data", "whole-foods-catalog.json");

let foodCount = 0;
let foodVersion = "n/a";
if (!existsSync(WEB_FOODS)) {
  console.warn(`WARN: no whole-foods catalog at ${WEB_FOODS} — skipping that mirror.`);
} else {
  let foods;
  try {
    foods = JSON.parse(readFileSync(WEB_FOODS, "utf8"));
  } catch (e) {
    die(`web whole-foods-catalog.json is not valid JSON: ${e.message}`);
  }
  const list = Array.isArray(foods.foods) ? foods.foods : [];
  const scoredFoods = list.filter((f) => f.score != null).length;
  // Same guard as the supplement catalog: never mirror an empty/broken export.
  if (scoredFoods < 1) {
    die(
      `web whole-foods catalog has ${scoredFoods} scored foods — refusing to ` +
        `mirror a broken catalog over the landing.`,
    );
  }
  writeFileSync(LANDING_FOODS, JSON.stringify(foods, null, 2) + "\n");
  foodCount = list.length;
  foodVersion = foods.version || "n/a";
}


/* ── the other four catalogs ──────────────────────────────────────────────
 *
 * The landing shipped three catalogs (supplements, whole foods, recipes) and
 * the homepage's pillar picker had five chips. Two of them filtered; the other
 * three could only say "browse →" and point into the app, which reads as
 * "coming soon" about catalogs that have been live for weeks.
 *
 * They were not gated. The data simply was not here. So it is mirrored the
 * same way the supplement catalog is, for the same reason: one source of
 * truth in the web app, copied rather than re-derived.
 *
 * NOT ALL OF THEM CARRY A SCORE, AND THEY ARE NOT MADE TO.
 *   personal care  666 products across four files, every one scored
 *   fitness        133 products, 72 scored, and that number is a rank INSIDE
 *                  a category (rank / ranked_of / comparison_label) — not a
 *                  cross-catalog score
 *   sleep          552 products, no score field at all. It carries price
 *                  bands, because a sleep mask and a mattress share no
 *                  attribute one number could rank.
 * The guard below is therefore per-catalog: a scored catalog must arrive with
 * scores, and an unscored one must not be failed for lacking them. Demanding
 * scores everywhere would have refused sleep forever; demanding none would let
 * a broken personal-care export through silently.
 */
const GEAR = [
  { file: "skin-catalog.json", label: "personal care · skin", assets: ["skin-assets"], mustScore: true },
  { file: "hair-catalog.json", label: "personal care · hair", assets: ["hair-assets"], mustScore: true },
  { file: "oral-catalog.json", label: "personal care · oral", assets: ["oral-assets"], mustScore: true },
  { file: "body-catalog.json", label: "personal care · body", assets: ["body-assets"], mustScore: true },
  { file: "fitness-catalog.json", label: "fitness gear", assets: ["images/fitness"], mustScore: false },
  { file: "sleep-catalog.json", label: "sleep gear", assets: ["sleep-assets"], mustScore: false },
];

const gearReport = [];
for (const g of GEAR) {
  const src = join(WEB_ROOT, "src", "data", g.file);
  const dest = join(LANDING_ROOT, "src", "data", g.file);
  if (!existsSync(src)) {
    console.warn(`WARN: no ${g.file} at ${src} — skipping that mirror.`);
    continue;
  }
  let data;
  try {
    data = JSON.parse(readFileSync(src, "utf8"));
  } catch (e) {
    die(`web ${g.file} is not valid JSON: ${e.message}`);
  }
  const list = Array.isArray(data.products) ? data.products : [];
  if (list.length < 1) die(`web ${g.file} holds no products — refusing to mirror it.`);
  const scored = list.filter((x) => typeof x.score === "number").length;
  if (g.mustScore && scored < 1) {
    die(`web ${g.file} has 0 scored products but is a scored catalog — refusing to mirror.`);
  }
  writeFileSync(dest, JSON.stringify(data, null, 2) + "\n");

  /* ONE FILE PER PRODUCT, not the directory it sits in.
     The supplement mirror above copies whole product directories because the
     landing opens supplement galleries. Nothing here does — gear shows a
     single picture — so copying the directory would bring 1,909 files to use
     1,085 of them.
     It is also the only thing that survives. `cpSync(..., {recursive:true})`
     in a tight loop crashed node outright on this machine (exit 0xC0000409,
     STACK_BUFFER_OVERRUN) partway through the second catalog, after writing
     skin and its assets. Not a path problem: no reparse points anywhere in
     these trees and the deepest path is 138 characters. copyFileSync does not
     do it. */
  let gearCopied = 0;
  let gearMissing = 0;
  const seen = new Set();
  for (const x of list) {
    const u = x.image_url || x.image;
    if (!u || typeof u !== "string" || !u.startsWith("/")) continue;
    const rel = u.split("?")[0].slice(1);
    if (!rel || seen.has(rel)) continue;
    seen.add(rel);
    const from = join(WEB_ROOT, "public", rel);
    const to = join(LANDING_ROOT, "public", rel);
    if (!existsSync(from)) {
      gearMissing += 1;
      continue;
    }
    mkdirSync(dirname(to), { recursive: true });
    copyFileSync(from, to);
    gearCopied += 1;
  }
  gearReport.push(
    `  ${g.label.padEnd(22)} ${String(list.length).padStart(4)} products, ` +
      `${String(scored).padStart(4)} scored, ${String(gearCopied).padStart(4)} images` +
      (gearMissing ? `, ${gearMissing} missing` : ""),
  );
}

/* List-sized thumbs for the gear photos just copied (see make-thumbs.mjs).
   Never fatal: a product without one renders its full photo. */
await makeThumbs({ root: LANDING_ROOT, log: (line) => gearReport.push(line) });

console.log("=== Landing catalog mirrored from web app ===");
console.log(`  source : ${WEB_CATALOG}`);
console.log(`  products: ${products.length} (${scored} scored/visible), brands: ${brands.length}`);
console.log(`  image dirs referenced: ${dirs.size} — copied/refreshed: ${copied}` +
  (missing ? `, missing source (will 404): ${missing}` : ""));
console.log(`  whole foods: ${foodCount} (export ${foodVersion})`);
for (const line of gearReport) console.log(line);
console.log("");
console.log("Next: commit src/data/catalog.json, src/data/whole-foods-catalog.json");
console.log("      + public/images/products, then push.");
